<script setup>
import {ref,computed,onMounted,onBeforeUnmount,nextTick,watch} from 'vue';
import SettingsIcon from './SettingsIcon.vue';
const props=defineProps({modelValue:{type:Array,default:()=>[]},options:{type:Array,default:()=>[]},label:String,placeholder:String,icon:String,allowCreate:Boolean,disabled:Boolean,chipsBelow:Boolean,inputId:String});
const emit=defineEmits(['update:modelValue']);
const root=ref(),input=ref(),panel=ref(),query=ref(''),open=ref(false),active=ref(0);
const id='chip-'+crypto.randomUUID();const normalize=value=>value.trim().toLocaleLowerCase();
const choices=computed(()=>{const text=query.value.trim();const selected=new Set(props.modelValue.map(normalize));const available=[...new Set(props.options)].filter(v=>!selected.has(normalize(v))&&normalize(v).includes(normalize(text))).map(value=>({value,label:value}));if(props.allowCreate&&text&&!props.options.some(v=>normalize(v)===normalize(text))&&!selected.has(normalize(text)))available.unshift({value:text,label:'Crear «'+text+'»',create:true});return available;});
function add(value){if(props.disabled)return;if(!props.modelValue.some(v=>normalize(v)===normalize(value)))emit('update:modelValue',[...props.modelValue,value]);query.value='';active.value=0;input.value.focus();}
function remove(value){if(!props.disabled)emit('update:modelValue',props.modelValue.filter(v=>v!==value));}
function keys(e){if(props.disabled)return;if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();if(!open.value){open.value=true;active.value=0;}else active.value=Math.max(0,Math.min(choices.value.length-1,active.value+(e.key==='ArrowDown'?1:-1)));nextTick(()=>panel.value?.querySelector('[aria-selected="true"]')?.scrollIntoView({block:'nearest'}));}else if(e.key==='Enter'&&!e.ctrlKey&&!e.metaKey){e.preventDefault();if(choices.value[active.value])add(choices.value[active.value].value);}else if(e.key==='Backspace'&&!query.value&&props.modelValue.length){remove(props.modelValue.at(-1));}else if(e.key==='Escape'&&open.value){e.preventDefault();e.stopPropagation();open.value=false;}else if(e.key==='Tab'){open.value=false;}}
function position(){if(!open.value||!panel.value||!root.value)return;const rect=root.value.querySelector('.chip-control').getBoundingClientRect(),height=panel.value.getBoundingClientRect().height,width=Math.min(rect.width,innerWidth-32);Object.assign(panel.value.style,{width:width+'px',left:Math.max(16,Math.min(rect.left,innerWidth-width-16))+'px',top:(innerHeight-rect.bottom>=height+16?rect.bottom+6:Math.max(16,rect.top-height-6))+'px'});}
watch(open,async value=>{await nextTick();if(value){panel.value.showPopover();position();}else if(panel.value?.matches(':popover-open'))panel.value.hidePopover();});watch(query,()=>{active.value=0;open.value=true;nextTick(position);});watch(choices,()=>nextTick(position));watch(()=>props.disabled,value=>{if(value)open.value=false;});
function outside(e){if(!root.value?.contains(e.target)&&!panel.value?.contains(e.target))open.value=false;}
onMounted(()=>{document.addEventListener('pointerdown',outside,true);window.addEventListener('resize',position);document.addEventListener('scroll',position,true);});
onBeforeUnmount(()=>{document.removeEventListener('pointerdown',outside,true);window.removeEventListener('resize',position);document.removeEventListener('scroll',position,true);});
</script>
<template><div ref="root" class="chip-input" :class="{disabled}"><div class="chip-control" @click="!disabled && !$event.target.closest('button') && input.focus()"><SettingsIcon :name="icon||'search'"/><div class="chip-values"><template v-if="!chipsBelow"><span v-for="value in modelValue" :key="value" class="product-chip">{{value}}<button type="button" :disabled="disabled" :aria-label="'Quitar '+value" @click="remove(value)"><SettingsIcon name="x"/></button></span></template><input :id="inputId" ref="input" v-model="query" :aria-label="label" :placeholder="placeholder" :disabled="disabled" role="combobox" autocomplete="off" :aria-expanded="open" :aria-controls="id" :aria-activedescendant="open&&choices.length?id+'-'+active:undefined" @focus="open=true" @keydown="keys"/></div></div><div v-if="chipsBelow&&modelValue.length" class="chip-below-values"><span v-for="value in modelValue" :key="value" class="product-chip">{{value}}<button type="button" :disabled="disabled" :aria-label="'Quitar '+value" @click="remove(value)"><SettingsIcon name="x"/></button></span></div><div ref="panel" popover="manual" :id="id" class="chip-suggestions mochi-night" role="listbox" :aria-label="label" aria-multiselectable="true"><button v-for="(choice,i) in choices" :id="id+'-'+i" :key="choice.value" type="button" role="option" tabindex="-1" :aria-selected="active===i" :class="{create:choice.create}" @pointerdown.prevent @click="add(choice.value)"><SettingsIcon v-if="choice.create" name="plus"/>{{choice.label}}</button><p v-if="!choices.length">{{query?'Sin coincidencias':'No hay más opciones'}}</p></div></div></template>
<style>
.chip-input{min-width:0}.chip-input.disabled{opacity:.5}.chip-control{display:flex;align-items:flex-start;gap:10px;min-height:48px;padding:0 12px;background:var(--surface);border:1px solid var(--border);border-radius:12px}.chip-control:focus-within{border-color:var(--accent);box-shadow:0 0 0 3px rgba(242,167,195,.2)}.chip-control>svg{margin-top:14px;flex:none;width:18px;height:18px;color:var(--text-muted)}.chip-values{display:flex;flex-wrap:wrap;align-items:center;flex:1;min-width:0;gap:4px}.chip-values>input{height:46px;flex:1;min-width:120px;width:100%;background:none;border:0;outline:none;color:var(--text);font-size:13px;padding:0!important;margin:0;font-family:inherit;box-shadow:none!important}.chip-values>input::placeholder{color:var(--placeholder)}.product-chip{display:inline-flex;align-items:center;gap:2px;background:var(--accent-tint);border-radius:999px;color:var(--accent);font-size:11px;padding-left:10px}.product-chip>button{display:flex;align-items:center;justify-content:center;min-width:44px;min-height:44px;padding:0;background:none;border:0;color:inherit}.product-chip svg{width:13px;height:13px}.chip-suggestions{position:fixed;inset:auto;margin:0;border:1px solid var(--border);border-radius:12px;padding:6px;background:#2b2138;box-sizing:border-box;max-height:210px;overflow:auto;box-shadow:0 12px 35px #0006;z-index:3000}.chip-suggestions:not(:popover-open){display:none}.chip-suggestions button{display:flex;align-items:center;gap:8px;width:100%;min-height:44px;text-align:left;padding:8px 12px;border:0;background:none;color:var(--text-soft);font:12px 'Plus Jakarta Sans',sans-serif;border-radius:8px}.chip-suggestions button[aria-selected=true],.chip-suggestions button:hover{background:var(--accent-tint);color:var(--text)}.chip-suggestions button.create{color:var(--accent);font-weight:700}.chip-suggestions p{color:var(--text-muted);font-size:12px;padding:8px 12px}.chip-suggestions svg{width:16px;height:16px}
</style>
